import { Component } from '@angular/core';
import { environment } from '../../../../../environments/environment';
import { ActivatedRoute, RouterModule } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-readmore-case-studies',
  standalone: true,
  imports: [CommonModule,RouterModule],
  templateUrl: './readmore-case-studies.component.html',
  styleUrl: './readmore-case-studies.component.scss'
})
export class ReadmoreCaseStudiesComponent {
   mainBlog: any = null;
    latestBlogs: any[] = [];
    loading = true;
  
    constructor(private http: HttpClient, private route: ActivatedRoute) { }
  
    ngOnInit(): void {
      this.route.queryParamMap.subscribe(params => {
        const id = params.get('id');
        if (id) {
          this.fetchNews(id);
        }
      });
    }
  
    fetchNews(id: string) {
      this.http.get<any>(`${environment.apiUrl}/case-study`).subscribe({
        next: (res) => {
          if (res?.success && res.data?.data) {
            const allNews = res.data.data;
  
            this.mainBlog = allNews.find((n: any) => String(n.id) === id);
  
            this.latestBlogs = allNews
              .filter((n: any) => String(n.id) !== id)
              .slice(0, 3);
          }
          this.loading = false;
        },
        error: (err) => {
          console.error('Error fetching news:', err);
          this.loading = false;
        }
      });
    }
}
